"До ступени «{0}» — ещё {1}.":"「{0}」の段階まであと{1}です。",
"Награду Орден выдаст, когда Кощей расколет камень, — по вкладу за сезон. Чем больше вклад, тем она щедрее.":"コシチェイが石を砕いたときに、シーズン中の貢献に応じて捕り手団から報酬が渡されます。貢献が大きいほど、報酬も豪華になります。",
