"Оберег":"お守り",
"Узелок с заговорённой травой. Бросай в духа, чтобы поймать.":"まじないをかけた薬草の包み。精霊に投げて捕まえましょう。",
"Серебряный оберег":"銀のお守り",
"Серебро держит духов крепче. Шанс поимки ×1,5.":"銀は精霊をしっかりつかまえます。捕獲率×1.5。",
"Золотой оберег":"金のお守り",
"Лучший оберег Ордена. Шанс поимки ×2.":"捕り手団で最高のお守り。捕獲率×2。",
"Духи обожают мёд. Успокаивает духа: шанс поимки ×1,5 на один бросок.":"精霊はハチミツが大好き。精霊を落ち着かせます：1投だけ捕獲率×1.5。",
"Подорожник":"オオバコ",
"Лист к ране — и полегчало. Возвращает духу четверть здоровья.":"傷に葉を当てれば、すっと楽に。精霊の体力を4分の1回復します。",
"Целебный отвар":"薬湯",
"Травы Велеса, сваренные в воде из источника. Возвращает духу 60% здоровья.":"泉の水で煮出したヴェレスの薬草。精霊の体力を60%回復します。",
"Мёртвая вода":"死の水",
"Редкая сказочная вода, что сращивает самые тяжкие раны. Дух без сил поднимется на 4 часа раньше. Живых не лечит.":"どんな深い傷もふさぐ、レアなおとぎ話の水。戦闘不能の精霊が4時間早く復活します。戦闘不能でない精霊は回復しません。",
"Живая вода":"命の水",
"Возвращает духу половину здоровья, а в разломе — лечит прямо в бою. Духа без сил не поднимет.":"精霊の体力を半分回復し、裂け目ではバトル中に回復できます。戦闘不能の精霊は復活できません。",
"Ладан":"お香",
"Дымок приманивает духов: 30 минут их вокруг вдвое больше.":"煙が精霊を引き寄せます：30分間、まわりの精霊が2倍に。",
"Дальний пропуск":"遠隔パス",
"Грамота Ордена: закрыть Разлом до 5 км от тебя, не подходя к нему. Один Орден дарит каждый день.":"捕り手団の証書：5km以内の裂け目に近づかずに挑めます。毎日1枚、捕り手団から届きます。",
"Кольцо Ордена с воронкой дорог: шагни в любое место Атласа мира сразу, не дожидаясь перезарядки. Одни Врата дарят на седьмой день серии.":"道の渦を宿した捕り手団の環。待ち時間なしで、世界アトラスのどこへでもすぐに移動できます。連続ログイン7日目にひとつもらえます。",
