"Выведи духа из кокона":"繭から精霊をかえそう",
"Освободи источник от прислужников Нави":"ナヴィの手下から泉源を解放しよう",
"Миров духов всегда было много — у каждого народа свой: Навь у славян, царство Аида у греков, Асгард у скандинавов, холмы сидов у кельтов, Дуат у египтян, Небеса у китайцев, Миктлан у ацтеков. На местах их держал <b>Алатырь</b> — бел-горюч камень в середине всех миров. Каждые врата вели в свою землю, и духи не путали дорог.":"精霊の世界は昔からたくさんあり、民ごとにそれぞれの世界がありました。スラヴのナヴィ、ギリシャのハデスの国、北欧のアスガルド、ケルトの妖精の丘、エジプトのドゥアト、中国の天界、アステカのミクトラン。それらを所定の場所につなぎとめていたのが、すべての世界の真ん中にある燃える白い石<b>アラトゥイリ</b>です。どの門も自分の土地へ通じていて、精霊たちが道を間違えることはありませんでした。",
"Однажды осенней ночью Кощей Бессмертный решил спрятать свою смерть понадёжнее — прямо в сердце Алатыря. Камень треснул и раскололся. Все врата распахнулись разом, дороги между мирами спутались в клубок, и духи и боги семи мифологий высыпали в наш мир — кто куда. Эту ночь назвали <b>Перепутицей</b>. Кощей уверяет, что камень треснул сам, но Локи и Сунь Укун при этих словах почему-то хихикают.":"ある秋の夜、不死身のコシチェイは自分の死をもっと安全な場所に隠そうと、アラトゥイリの心臓そのものに押しこみました。石はひび割れ、真っ二つに。すべての門がいっせいに開き、世界と世界をつなぐ道は毛糸玉のようにもつれ、7つの神話の精霊と神々が私たちの世界へばらばらにこぼれ出たのです。この夜は<b>大もつれ</b>と呼ばれています。コシチェイは「石が勝手に割れたんだ」と言い張りますが、そのたびにロキと孫悟空がなぜかくすくす笑っています。",
"Теперь Гиппокамп плещется в московском фонтане, Леший гуляет по токийскому парку, а Ниссе греет котов в подъездах Каира. Любого духа можно встретить в любом уголке земли. Разломы — трещины от расколотого камня — открываются в каждом городе, а боги ставят святилища там, где осели: Капище по соседству с Пагодой, Храм через улицу от Пирамиды. Город рождает и своих, новых духов: Вайфайку, Трамвайника, Фонарника.":"今ではヒッポカンポスがモスクワの噴水で水しぶきを上げ、レーシーが東京の公園を散歩し、ニッセがカイロのアパートの階段で猫たちを温めています。どんな精霊にも、地球のどこでも出会えます。割れた石が残したひび――裂け目はどの街にも開き、神々は落ち着いた場所に聖所を建てます。カピシチェの隣に塔、ピラミッドの向かいに神殿といった具合です。街は自分だけの新しい精霊、ワイファイカ、トラムヴァイニク、フォナルニクも生み出しています。",
"Первыми с гостями поладили не учёные, а бабушки со своими оберегами: оказалось, оберег, сделанный с заботой, успокаивает любого духа, откуда бы тот ни был. Так появился <b>Орден Оберега</b> — союз Ловчих всех земель. Твоя задача — находить духов, ловить их оберегами, черпать силу из источников, закрывать разломы и собирать осколки Алатыря. Кто знает — может, однажды их хватит, чтобы распутать дороги домой.":"来訪者たちと最初に仲よくなったのは、学者ではなく、お守りを手にしたおばあちゃんたちでした。心をこめて作ったお守りは、どこから来た精霊でも落ち着かせるとわかったのです。こうして、あらゆる土地の捕り手の集まり<b>お守りの捕り手団</b>が生まれました。あなたの役目は、精霊を見つけてお守りで捕まえ、泉源から力をくみ、裂け目を閉じ、アラトゥイリの欠片を集めることです。いつか欠片がそろえば、もつれた家路をほどけるかもしれません。",
