"Быстрота и отвага":"速さと勇気",
"Наследники княжеских дружин под знаком сокола-Рарога. Когда Кощей расколол Алатырь, они первыми встали у Капищ и держат Навь громом Перуна.":"猛禽ラログの紋を掲げる、公たちの親兵の末裔。コシチェイがアラトゥイリを割ったとき、真っ先にカピシチェの前に立ち、ペルーンの雷でナヴィを押しとどめています。",
"Фаланга Олимпа":"オリュンポスのファランクス",
"Сова":"フクロウ",
"гоплит":"ホプリテス",
"Щит к щиту":"盾と盾を並べて",
"Ловчие, что сомкнули щиты под знаком совы Афины. В Перепутицу они стерегут храмы, чтобы тени Аида не вышли к живым.":"アテナのフクロウの紋のもとで盾を連ねた捕り手たち。大もつれのさなか、ハデスの亡霊が生者の世界に出てこないよう神殿を守っています。",
