"Верные, как волки Одина. Хирд стоит у рунных камней, пока не затянутся трещины к Гиннунгагапу.":"オーディンの狼のように忠実。ギンヌンガガプへの裂け目が閉じるまで、ヒルドはルーン石のそばに立ち続けます。",
"Братство Дуба":"オークの兄弟団",
"Медведь":"クマ",
"друид":"ドルイド",
"Сила и стойкость":"力と粘り強さ",
"Друиды и воины священных рощ под рукой медведицы Артио. Братство держит каменные круги, чтобы холмы сидов не распахнулись навсегда.":"雌熊アルティオに守られた、聖なる森のドルイドと戦士たち。妖精の丘が開きっぱなしにならないよう、兄弟団はストーンサークルを守っています。",
"Стражи Дуата":"ドゥアトの番人",
