"Солнце взойдёт снова":"日はまた昇る",
"Хранители солнечной ладьи Ра. Пока Алатырь расколот, стражи стоят у обелисков, чтобы ночь Дуата не поглотила рассвет.":"ラーの太陽の船の守り人。アラトゥイリが割れているあいだ、番人たちはドゥアトの夜が夜明けをのみこまないよう、オベリスクのそばに立っています。",
