"Воины под знаменем Лазурного дракона. В Перепутицу гвардия держит пагоды, чтобы Небесные врата не остались распахнутыми.":"青龍の旗のもとに集う戦士たち。大もつれのさなか、天の門が開きっぱなしにならないよう、近衛隊は塔を守っています。",
