"Солнце не должно погаснуть":"太陽を消してはならない",
"Самые отважные воины древних городов Америки. Орден держит пирамиды, чтобы из Миктлана не пришла вечная ночь.":"アメリカ大陸の古代都市でいちばん勇敢な戦士たち。ミクトランから永遠の夜が来ないよう、騎士団はピラミッドを守っています。",
