"Святки":"スヴャトキ",
"Зимние праздники: Морозко и Снегурка выходят к людям, духи Ветра и Воды встречаются чаще, в источниках — подарки.":"冬の祝祭：モロースコとスネグールカが人前に現れ、風と水の精霊が出やすくなり、泉源からプレゼントが出ます。",
"Масленица":"マースレニツァ",
"Провожаем зиму! Духи Огня встречаются вдвое чаще, в источниках много мёда («блинов»), опыт ×1,5.":"冬を見送ろう！火の精霊が2倍出やすくなり、泉源ではハチミツ（「ブリヌイ」）がたくさん。経験値×1.5。",
"Купальская ночь":"クパーラの夜",
"Цветёт папоротник: Купалинка повсюду, духи Огня, Воды и Леса чаще, ночью сияющие — вдвое чаще.":"シダの花が咲きます：クパリンカがあちこちに現れ、火・水・森の精霊が出やすくなり、夜は色違いが2倍出やすくなります。",
"Покров":"ポクロフ",
"Первые туманы и иней: духи Ветра и Воды встречаются чаще, Листопадница — повсюду, в источниках больше добычи.":"初霧と初霜：風と水の精霊が出やすくなり、リストパドニツァがあちこちに。泉源の収穫も増えます。",
"Велесова ночь":"ヴェレスの夜",
"Граница миров тоньше всего: духи Тени втрое чаще, в великих разломах ждёт Кощей, сияющие Тени вдвое чаще.":"世界の境界がもっとも薄くなる夜：影の精霊が3倍出やすく、大裂け目ではコシチェイが待ち受け、影の色違いが2倍出やすくなります。",
"Этот источник теперь принадлежит Нави!":"この泉源はもうナヴィのものだ！",
"Твои духи будут служить Кощею!":"お前の精霊はコシチェイ様にお仕えするのだ！",
"Орден Оберега? Никогда о таком не слышал.":"お守りの捕り手団？聞いたこともないね。",
"Граница рухнет, и мы заберём весь город!":"境界は崩れ、この街はまるごと我らのものになる！",
"Думаешь, оберегом меня остановишь?":"お守りなんかで止められると思ってるのか？",
"Тьма уже здесь, Ловчий. Смирись.":"闇はもうここにある、捕り手よ。あきらめろ。",
