"Венок с цветком папоротника, что расцветает лишь в Купальскую ночь.":"クパーラの夜にだけ咲くシダの花をあしらった花冠。",
"Капюшон из мха и оленьи рога — леса признают тебя своим.":"苔のフードと鹿の角。森があなたを仲間と認めます。",
