"Шапка с рунами и посох с огоньком: мудрость старых волхвов.":"ルーン文字の帽子と、灯のともる杖。古の賢者の知恵。",
"Богатырь":"ボガトィーリ",
"Шелом, кольчуга и алое корзно — хоть сейчас на заставу.":"兜、鎖かたびら、真紅のマント。今すぐ砦の守りにつけそう。",
"Вороний":"ワタリガラス",
"Маска-клюв и плащ из чёрных перьев. Вороны Нави шепчут тебе вести.":"くちばしの仮面と黒い羽根のマント。ナヴィのカラスがあなたに知らせをささやきます。",
"Навий страж":"ナヴィの番兵",
"Рогатая личина и пламя Нави. Духи расступаются перед тобой.":"角のある仮面とナヴィの炎。精霊たちが道をあけます。",
