"Ледяной узор":"氷の模様",
"Огненная кайма":"炎の縁取り",
"Жемчужная":"真珠",
"Змей-уроборос":"ウロボロスの竜",
"Навий шип":"ナヴィのとげ",
"Княжий оклад":"公の飾り枠",
"Поединщик":"決闘士",
"Победи хранителей капищ":"倒したカピシチェの守護者",
"Победи хранителей капищ: {0}":"カピシチェの守護者を倒そう：{0}",
"Первый дух":"最初の精霊",
"Твои духи":"あなたの精霊",
"Источники":"泉源",
"Рядом появился дух — видишь светящийся круг на карте? <b>Коснись духа</b>, а потом <b>смахни оберег вверх</b>, прямо в него.":"近くに精霊が現れた。マップに光る円が見えるかい？<b>精霊をタップ</b>して、それから<b>お守りを上にスワイプ</b>、まっすぐ精霊に向けて。",
"Второй учебный дух рядом. Кольцо вокруг духа сжимается: бросай, когда оно <b>маленькое</b>, — выйдет «Отлично!». Зелёное кольцо — дух покладистый, красное — упрямый.":"2体目の練習用の精霊が近くにいる。精霊のまわりのサークルは縮んでいく。<b>小さい</b>ときに投げると「グレート！」になる。緑のサークルはおとなしい精霊、赤は頑固な精霊。",
"Это меню — здесь все разделы. Пока открыто не всё: разделы откроются по ходу обучения, подсвеченный — следующий.":"これがメニュー。すべての項目がここにある。まだ全部は開いていない。チュートリアルを進めると開いていき、光っているのが次の項目。",
"Каждый пойманный дух — твой. Открой <b>меню</b> — золотой оберег внизу экрана.":"捕まえた精霊はすべて君のものだ。画面下の金のお守り、<b>メニュー</b>を開いてごらん。",
"Это твоя коллекция — все пойманные духи. Сверху — сортировка по силе, новизне и имени и фильтр по стихиям.":"これが君のコレクション、捕まえた精霊すべてだ。上ではパワー・新しさ・名前で並べ替えたり、属性で絞り込んだりできる。",
"Это разделы Ордена. Открой <b>«Духи»</b> — там твоя коллекция.":"これが捕り手団の各項目だ。<b>「精霊」</b>を開いてごらん。君のコレクションがある。",
"Это карточка духа: сила, стихия, приёмы и семейство. Ниже — кнопки «Усилить» и «Превратить», а ещё можно сделать духа спутником.":"これは精霊のカードだ。パワー、属性、技、系統がわかる。下には「強化」と「進化」のボタンがあり、精霊を相棒にすることもできる。",
"Коснись любого духа, чтобы открыть его <b>карточку</b>.":"どれか精霊をタップして、<b>カード</b>を開いてごらん。",
"На карточке — сила духа. Нажми <b>«Усилить»</b>: за искры и эссенцию дух станет сильнее. Эссенцию приносят поимки духов того же семейства.":"カードには精霊のパワーが表示される。<b>「強化」</b>を押そう。火の粉とエッセンスで精霊が強くなる。エッセンスは同じ系統の精霊を捕まえると手に入る。",
"Бестиарий — все виды духов. Пойманные видны целиком, встреченные — тенью. Коснись вида, чтобы прочитать о нём.":"図鑑にはすべての種類の精霊が載っている。捕まえたものは全身が、出会っただけのものは影で見える。種類をタップすると説明が読める。",
"Теперь загляни в <b>«Бестиарий»</b> (меню) — там все виды духов. Сколько найдёшь ты?":"今度はメニューの<b>「図鑑」</b>をのぞいてごらん。すべての種類の精霊がいる。君はいくつ見つけられるかな？",
"Обереги пополняют <b>источники</b> — светящиеся чаши у памятников, фонтанов и храмов. Дойди до ближайшего джойстиком по <b>стрелке вверху</b> и коснись его. Если рядом нет — прогуляйся по карте.":"お守りは<b>泉源</b>で補充できます。泉源は記念碑や噴水、寺社のそばにある光る器です。<b>画面上の矢印</b>に従ってジョイスティックでいちばん近い泉源まで歩き、タップしてください。近くになければ、マップを少し歩いてみましょう。",
"Сумка: обереги, мёд, живая вода и ладан. Сверху видно, сколько ещё поместится; лишнее можно выбросить.":"バッグ：お守り、ハチミツ、命の水、お香。上にはあといくつ入るかが表示される。いらないものは捨てられる。",
"Добыча уже в <b>Сумке</b>. Открой меню → «Сумка» и посмотри, что у тебя есть.":"手に入れたものはもう<b>バッグ</b>の中だ。メニュー →「バッグ」を開いて、何があるか見てみよう。",
"Коконы греются шагами — одновременно можно греть три. Готовый кокон вылупится одним касанием. А твой первый дух идёт рядом — это спутник: в пути он находит эссенцию.":"繭は歩いて温める。同時に温められるのは3つまで。準備ができた繭はタップ1回でかえる。最初の精霊はそばを歩く相棒。道中でエッセンスを見つけてくれる。",
"Открой меню → <b>«Коконы»</b>. Первый кокон уже греется — пройди 2 км, и он вылупится.":"メニュー →<b>「繭」</b>を開こう。最初の繭はもう温まり始めている。2km歩けばかえるよ。",
"Здесь задания дня — они обновляются в полночь. А источники иногда дают поручения: выполнишь — встретишь особого духа.":"ここは今日の任務。毎日0時に更新される。泉源はときどき依頼もくれる。こなすと特別な精霊に出会える。",
"Открой <b>«Задания»</b> — там задания дня.":"<b>「任務」</b>を開こう。今日の任務がある。",
"Путь Ловчего: что откроется на каждом уровне и какие награды ждут. Звания растут: Послушник, Ловчий, Следопыт, Ведун, Хранитель.":"捕り手の道：各レベルで解放されるものと、待っている報酬がわかる。称号も上がっていく。見習い、捕り手、追跡者、賢者、守護者。",
"И последнее: открой <b>«Путь»</b> в меню — там видно, что откроется на каждом уровне Ловчего.":"最後に、メニューの<b>「道」</b>を開いてごらん。捕り手の各レベルで何が解放されるかがわかる。",
