"Поражение":"敗北",
"«Приходи, когда окрепнешь», — говорит {0}. Попробуй другую команду: смотри на стихии хранителя и береги щиты для его приёмов.":"「強くなってから来るがよい」と{0}が言います。別のチームで挑戦してみましょう。守護者の属性に注目して、シールドは守護者の技のためにとっておきましょう。",
"Хорошая тренировка! Награда за поединок с {0} сегодня уже получена.":"いい練習になりました！{0}との決闘の報酬は今日はもう受け取っています。",
"{0} жмёт тебе руку: «Честный бой!» Дружба крепнет.":"{0}が握手を求めてきました。「正々堂々のいい勝負だった！」フレンド度がアップ。",
