"На карте":"マップで見る",
"Записей пока нет. Лови духов — дневник заполнится сам.":"まだ記録はありません。精霊を捕まえれば、日誌は自然に埋まっていきます。",
"Поиск соперника":"対戦相手を探す",
"Ищу живого Ловчего…":"本物の捕り手を探しています…",
