"Сейчас ищут соперника: {0}":"いま相手を探している人：{0}",
"Пока ищешь только ты — позови друзей в Лигу":"探しているのはあなただけ。フレンドをリーグに誘いましょう",
"Сейчас в Лиге мало Ловчих — попробуй позже":"いまリーグには捕り手が少なめです。あとで試してください",
"Соперник найден!":"相手が見つかりました！",
"ур. {0} · сила команды {1}":"Lv.{0} · チームのパワー {1}",
"Бой через":"バトル開始まで",
"Соперник — живой Ловчий. Тапай — быстрая атака, она копит энергию; полная шкала — «Приём». Щиты берегут от его приёмов.":"相手は本物の捕り手。タップで速攻、エネルギーがたまります。ゲージが満タンで「技」。シールドで相手の技を防げます。",
"Нет связи с сервером — переподключаюсь…":"サーバーとの接続が切れました。再接続中…",
