"{0} выбирает духа…":"{0}が精霊を選んでいます…",
"Приём соперника…":"相手の技…",
"Бой будет проигран, рейтинг уменьшится, опыта не будет.":"このバトルは負けになり、レートが下がり、経験値はもらえません。",
"Все духи {0} без сил.":"{0}の精霊が全員戦闘不能。",
