"Заходи каждый день — награды растут, а на 7-й день ждёт кокон 10 км.":"毎日ログインしよう。報酬はどんどん増え、7日目には10kmの繭が待っています。",
"Седьмой день! Завтра круг начнётся снова — серия продолжается.":"7日目！明日からまた一巡目が始まります。連続記録は続きます。",
