"Опыт отдыха: следующие {0} опыта — вдвое":"休息ボーナス：次の経験値{0}が2倍",
"За день опыт идёт полностью до {0}, дальше до {1} — вполовину, сверх — на четверть. Обучение и знаки Ордена дают опыт всегда полностью. За каждый день без игры копится опыт отдыха ({2}, не больше чем за {3} {4}): пока он есть, опыт вдвое.":"1日の経験値は{0}まで全額、{1}までは半分、それ以上は4分の1。チュートリアルと団のバッジの経験値はいつでも全額です。プレイしなかった日ごとに休息ボーナスがたまり（{2}、最大{3}{4}分）、残っている間は経験値が2倍。",
