"дальше: {0} на {1}":"次は：Lv.{1}で{0}",
"Опыт дают поимки, источники, разломы, капища и задания. С уровнем растут и твои духи: их можно усиливать до уровня Ловчего +5.":"経験値は、捕獲、泉源、裂け目、カピシチェ、任務で手に入ります。レベルが上がると精霊も成長し、捕り手のレベル+5まで強化できます。",
"С {0} уровня духов можно пробуждать: каждая звезда поднимает предел уровня духа ещё на {1}, до {2}.":"Lv.{0}から精霊を覚醒できます。星1つごとに精霊のレベル上限がさらに{1}上がり、最大{2}まで。",
"Ищу настоящие места вокруг — Источники и Капища появятся через несколько секунд":"近くの実在スポットを検索中。泉源とカピシチェは数秒で現れます",
"Посылка из Ордена":"捕り手団からの小包",
"Поблизости пока нет ни одного Источника, поэтому Орден раз в день присылает припасы: {0}.":"近くにまだ泉源がひとつもないので、捕り手団が1日1回道具を送ってくれます：{0}。",
