"<b>Подходят:</b> памятники, скульптуры, фонтаны, мозаики, необычные здания, храмы, парки, источники, смотровые площадки.":"<b>OK：</b>記念碑、彫刻、噴水、モザイク、珍しい建物、寺院、公園、泉、展望台。",
"<b>Не подходят:</b> частные дома и дворы, школы и детские сады, опасные места (проезжая часть, стройки), обычные магазины.":"<b>NG：</b>個人の住宅や庭、学校や幼稚園、危険な場所（車道、工事現場）、ふつうの商店。",
"Стой рядом с объектом: снимок получает геометку, модератор сверяет её с точкой на карте.":"スポットのそばに立ってください。写真に位置情報がつき、モデレーターがマップ上の地点と照合します。",
