"Там, где Алатырь дал трещину, из-под земли бьёт вода Перепутицы. У Источников Ловчие всех земель черпают обереги и припасы.":"アラトゥイリが裂けた場所から、大もつれの水が湧き出ます。あらゆる土地の捕り手が泉源でお守りや物資を汲み取ります。",
