"Весь мир — твой":"世界はあなたのもの",
"Перепутица спутала дороги мира, и Орден Оберега открыл Ловчим Врата: выбери в Атласе мира любой уголок Земли — там и начнёшь охоту. По карте ходи джойстиком, а в новые края шагай через Атлас. Настоящее местоположение телефона игре не нужно. Прогресс хранится на сервере игры и доступен только тебе; сервер проверяет каждое действие, поэтому нужен интернет. Места на карте и погода загружаются для выбранного района у OpenStreetMap и Open-Meteo (погоду можно выключить в настройках).":"大もつれが世界の道をもつれさせ、お守りの捕り手団は捕り手たちに門を開きました。世界アトラスで地球のどこでも選んでください。そこから狩りが始まります。マップはジョイスティックで歩き、新しい土地へはアトラスから移動します。スマートフォンの本当の位置情報は必要ありません。進行状況はゲームサーバーに保存され、あなただけが見られます。サーバーがすべての操作を確認するため、インターネット接続が必要です。選んだ地域のマップ上の場所と天気は OpenStreetMap と Open-Meteo から読み込みます（天気は設定でオフにできます）。",
"В путь":"出発",
