"Привяжи вход: Меню → Настройки → Учётная запись (Google, Яндекс, VK, Telegram или почта). Без этого прогресс гостя не перенесётся.":"ログインを連携してください：メニュー → 設定 → アカウント（Google、Yandex、VK、Telegram、メール）。連携しないと、ゲストのデータは引き継がれません。",
